class Solution:
    def shortestBeautifulSubstring(self, s: str, k: int) -> str:
        # find the beautiful substrings
        # find the smallest one in terms of lexicography and length
        l = 0
        ans = 0
        num_of_ones = 0
        min_len = 101
        valid = []

        for r in range(len(s)):
            if s[r] == "1":
                num_of_ones += 1

            while num_of_ones == k:
                min_len = min(min_len, r - l + 1)
                valid.append(s[l:r + 1])
                if s[l] == "1":
                    num_of_ones -= 1
                l += 1
        ans = sorted(list(filter(lambda x: len(x) == min_len, valid)))
        if not ans:
            return ""
        return ans[0]
